"""How a node runs: its `Implementation`, whatever writes the body of its node function.

The planner chooses one implementation per node (`plan.Step`), and the node's signature
follows from what it declares (`signature.node_signature`). Codegen builds every node
function the same way (`node.node_function`), and the implementation writes its body:

* `Generated`: code generated by the op's emitter (`llvm_emit`), inlined;
* `RustKernel`, `NumbaKernel`: a call of a kernel through the kernel ABI;
* `OwnModule`: generated code compiled in a module of its own, called like a kernel.

Every implementation declares the same things, for the layouts of the node's inputs:
the layout of each output and whether it can write into memory the caller provides
(`OutputDeclaration`), whether its outputs may be views of its inputs (`may_view`), and
which inputs it overwrites (`can_overwrite`: those the planner lets it,
`always_overwrites`: these, whatever the planner allows; the node function passes copies
of those that aren't writable).
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Protocol

from pytensor.graph.basic import Apply
from pytensor.link.llvm.analysis.layout import Layout
from pytensor.link.llvm.codegen.types import element_type, is_absent


if TYPE_CHECKING:
    from pytensor.link.llvm.codegen.call import Callee, Kernel
    from pytensor.link.llvm.codegen.context import Codegen
    from pytensor.link.llvm.codegen.destination import OutputDestination
    from pytensor.link.llvm.codegen.interface import EmitterInput
    from pytensor.link.llvm.codegen.kernel_module import KernelModule
    from pytensor.link.llvm.codegen.signature import Signature


@dataclass(frozen=True)
class OutputDeclaration:
    """What an implementation declares about one output of its node."""

    #: its layout; None: the default (C for new memory, nothing known for a view)
    layout: Layout | None = None
    #: can it write into memory the caller provides? Else it allocates (a slot).
    writes_provided: bool = True


class Implementation(Protocol):
    """How a node runs: what writes the body of its node function."""

    @property
    def description(self) -> str:
        """For error messages and debug names."""
        ...

    @property
    def may_view(self) -> bool:
        """May its outputs be views of the inputs its op's `view_map` lists?"""
        ...

    @property
    def can_overwrite(self) -> bool:
        """May it overwrite the inputs the planner lets it (`Signature.writable`)?"""
        ...

    @property
    def always_overwrites(self) -> frozenset[int]:
        """Inputs it overwrites whatever the planner allows: the node function passes
        copies of those that aren't writable."""
        ...

    @property
    def allocates_through_codegen(self) -> bool:
        """Are its new outputs allocated by codegen (`OutputDestination.allocate`), so
        that they may go into scratch memory? Else a kernel allocates them."""
        ...

    def outputs(
        self, node: Apply, in_layouts: Sequence[Layout | None]
    ) -> list[OutputDeclaration]:
        """What it declares about each output of `node`, for these input layouts
        (DYNAMIC where unknown: `signature.known_layouts`)."""
        ...

    def emit(
        self,
        cg: Codegen,
        node: Apply,
        signature: Signature,
        inputs: list[EmitterInput],
        outputs: list[OutputDestination | None],
    ) -> None:
        """Write the node function's body: produce every output into its destination.
        `inputs` has one entry per node input (`interface.EmitterInput`)."""
        ...


@dataclass(frozen=True)
class Generated:
    """Code generated by the op's emitter (`llvm_emit`), inlined into the caller."""

    @property
    def description(self) -> str:
        return "generated"

    @property
    def may_view(self) -> bool:
        return True

    @property
    def can_overwrite(self) -> bool:
        return True

    @property
    def always_overwrites(self) -> frozenset[int]:
        return frozenset()

    @property
    def allocates_through_codegen(self) -> bool:
        return True

    def outputs(
        self, node: Apply, in_layouts: Sequence[Layout | None]
    ) -> list[OutputDeclaration]:
        from pytensor.link.llvm.codegen.interface import llvm_layout

        declared = llvm_layout(node.op, node, list(in_layouts))
        return [OutputDeclaration(layout) for layout in declared]

    def emit(
        self,
        cg: Codegen,
        node: Apply,
        signature: Signature,
        inputs: list[EmitterInput],
        outputs: list[OutputDestination | None],
    ) -> None:
        from pytensor.link.llvm.codegen.destination import ScalarDestination
        from pytensor.link.llvm.codegen.interface import (
            ScalarOutput,
            TensorOutput,
            llvm_emit,
        )
        from pytensor.link.llvm.codegen.signature import (
            destroyed_inputs,
            view_inputs,
        )

        handles: list[TensorOutput | ScalarOutput | None] = []
        for k, (destination, output) in enumerate(
            zip(outputs, signature.outputs, strict=True)
        ):
            if destination is None:
                handles.append(None)
            elif isinstance(destination, ScalarDestination):
                handles.append(ScalarOutput(destination))
            else:
                # (the inputs it may overwrite: those the signature lets it, with
                # layouts that give the output its own)
                aliased = output.aliased_inputs
                destroyed = tuple(i for i in destroyed_inputs(node, k) if i in aliased)
                handles.append(
                    TensorOutput(
                        destination,
                        output.tensor.layout,
                        view_inputs(node, k),
                        destroyed,
                    )
                )
        llvm_emit(node.op, node, cg, inputs, handles)
        if cg.b.terminated:
            return
        for k, destination in enumerate(outputs):
            if destination is not None:
                try:
                    destination.finish()
                except ValueError as e:
                    raise ValueError(f"{node.op}: output {k}: {e}") from None


#: The implementation of every generated node (it has no state).
GENERATED = Generated()


class _KernelCall:
    """What the implementations calling a kernel share: they call `callee` through the
    kernel ABI with the node's arguments, and their outputs are new memory, as
    `declarations` say."""

    declarations: tuple[OutputDeclaration, ...]

    @property
    def callee(self) -> Callee:
        raise NotImplementedError

    @property
    def description(self) -> str:
        raise NotImplementedError

    @property
    def may_view(self) -> bool:
        return False

    @property
    def can_overwrite(self) -> bool:
        return False

    @property
    def always_overwrites(self) -> frozenset[int]:
        return frozenset()

    @property
    def allocates_through_codegen(self) -> bool:
        return False

    def outputs(
        self, node: Apply, in_layouts: Sequence[Layout | None]
    ) -> list[OutputDeclaration]:
        return list(self.declarations)

    def emit(
        self,
        cg: Codegen,
        node: Apply,
        signature: Signature,
        inputs: list[EmitterInput],
        outputs: list[OutputDestination | None],
    ) -> None:
        from pytensor.link.llvm.codegen.call import KernelInput, call_kernel

        arguments = signature.argument_of_input
        values: list[KernelInput] = []
        for position, (value, var) in enumerate(zip(inputs, node.inputs, strict=True)):
            if arguments is not None and arguments[position] is None:
                continue  # (folded into the kernel's code, or without data)
            values.append(
                (value, None if is_absent(var.type) else element_type(var.type))
            )
        call_kernel(cg, self.callee, values, outputs)


@dataclass(frozen=True)
class RustKernel(_KernelCall):
    """A Rust kernel (kernels/rust.py), made for the layouts of the node's inputs: it
    chose the layouts of its outputs, and whether it writes them into memory the caller
    provides."""

    kernel: Kernel
    declarations: tuple[OutputDeclaration, ...]

    @property
    def callee(self) -> Callee:
        return self.kernel

    @property
    def description(self) -> str:
        return self.kernel.description


@dataclass(frozen=True)
class NumbaKernel(_KernelCall):
    """The op's numba implementation as a kernel (kernels/numba.py). It allocates its
    outputs, in the layouts it was compiled for, and overwrites the inputs its op
    destroys."""

    kernel: Kernel
    declarations: tuple[OutputDeclaration, ...]
    #: the inputs its op destroys
    destroys: frozenset[int] = field(default=frozenset(), kw_only=True)

    @property
    def callee(self) -> Callee:
        return self.kernel

    @property
    def description(self) -> str:
        return self.kernel.description

    @property
    def always_overwrites(self) -> frozenset[int]:
        return self.destroys


@dataclass(frozen=True, eq=False)
class OwnModule(_KernelCall):
    """Generated code compiled in a module of its own (`unit`, built from `inner` with
    the same signature), called like a kernel: a step of the program. The module is
    linked with the program (`kernel_module.link`)."""

    unit: KernelModule
    declarations: tuple[OutputDeclaration, ...]
    inner: Implementation = field(default=GENERATED, kw_only=True)

    @property
    def callee(self) -> Callee:
        return self.unit

    @property
    def description(self) -> str:
        return self.unit.description

    @property
    def may_view(self) -> bool:
        return self.inner.may_view

    @property
    def can_overwrite(self) -> bool:
        return self.inner.can_overwrite

    @property
    def always_overwrites(self) -> frozenset[int]:
        return self.inner.always_overwrites


__all__ = [
    "GENERATED",
    "Generated",
    "Implementation",
    "NumbaKernel",
    "OutputDeclaration",
    "OwnModule",
    "RustKernel",
]
